import numpy as np
import pandas as pd

def _delta(g, col):
    g = g.sort_values("date")
    if g.empty:
        return np.nan
    s = g[col].astype(float)
    end = pd.to_datetime(g["date"].iloc[-1])
    mask = pd.to_datetime(g["date"]) >= (end - pd.Timedelta(days=13))
    sub = s[mask]
    if sub.empty or not sub.notna().any():
        return np.nan
    first = sub[sub.notna()].iloc[0]
    last = s.iloc[-1]
    if not (pd.notna(first) and pd.notna(last)):
        return np.nan
    return float(last - first)

def feature(history):
    col = "smart_196_raw"
    return history.groupby("serial_number", group_keys=False).apply(lambda g: _delta(g, col))

