import numpy as np
import pandas as pd

def feature(history):
    num_col = "smart_193_raw"
    def _ratio(g):
        g = g.sort_values("date")
        if g.empty:
            return np.nan
        num = float(g[num_col].astype(float).iloc[-1]) if pd.notna(g[num_col].iloc[-1]) else np.nan
        den = float(g["smart_9_raw"].astype(float).iloc[-1]) if pd.notna(g["smart_9_raw"].iloc[-1]) else 1.0
        if not np.isfinite(num):
            return np.nan
        return float(num / max(den, 1.0))
    return history.groupby("serial_number", group_keys=False).apply(_ratio)

