def feature(history):
    def _miss(g):
        g = g.sort_values("date")
        if g.empty:
            return np.nan
        end = pd.to_datetime(g["date"].iloc[-1])
        mask = pd.to_datetime(g["date"]) >= (end - pd.Timedelta(days=13))
        sub = g.loc[mask]
        cols = [c for c in sub.columns if c.endswith("_raw") and c.startswith("smart_")]
        if not cols:
            return np.nan
        arr = sub[cols].astype(float)
        return float(arr.isna().mean().mean())
    return history.groupby("serial_number", group_keys=False).apply(_miss)

