def feature(history):
    def _score(g):
        g = g.sort_values("date")
        if g.empty:
            return 0.0
        sub = g[K0].astype(float)
        observed = sub.notna().all(axis=1)
        if not observed.any():
            return 0.0
        last_row = sub.loc[observed].iloc[-1]
        if not (last_row.fillna(1) == 0).all():
            return 0.0
        s196 = float(g["smart_196_raw"].astype(float).iloc[-1]) if pd.notna(g["smart_196_raw"].iloc[-1]) else 0.0
        s10 = float(g["smart_10_raw"].astype(float).iloc[-1]) if pd.notna(g["smart_10_raw"].iloc[-1]) else 0.0
        end = pd.to_datetime(g["date"].iloc[-1])
        mask = pd.to_datetime(g["date"]) >= (end - pd.Timedelta(days=13))
        s192 = g.loc[mask, "smart_192_raw"].astype(float)
        inc = 0.0
        if s192.notna().any():
            first = s192[s192.notna()].iloc[0]
            last = s192.iloc[-1]
            if pd.notna(first) and pd.notna(last):
                inc = float(last - first)
        return float((s196 > 0) + (s10 > 0) + (inc > 0))
    return history.groupby("serial_number", group_keys=False).apply(_score)

